from pathlib import Path
import shutil

r=Path(__file__).resolve().parents[1];src=r/'preview/city-market03';dst=r/'preview/city-layout04';dst.mkdir(exist_ok=True)
for name in ['members.js','members.json','market-profiles.js','market-stock.js','clean-merch.js','pixel-reducer.js','merch-catalog.js','random-floor.js','visibility.js','visibility-paths.js','style.css','catalog.html','catalog.js']:
    shutil.copy2(src/name,dst/name)
shutil.copy2(src/'generator.js',dst/'legacy-generator.js')
shutil.copytree(src/'assets',dst/'assets',dirs_exist_ok=True)
html=(src/'index.html').read_text(encoding='utf-8').replace('上店','上店')
html=html.replace('상점가 · 축소 도트 비교','도시 구조 · 랜덤 생성 비교')
html=html.replace('<div class="toolbar">','<div class="layout-toolbar"><label for="layoutMode">지도 구조</label><select id="layoutMode"><option value="auto">층마다 랜덤 선택</option><option value="plaza">큰 광장·건물 덩어리</option><option value="rooms">비정형 방·통로 연결</option><option value="alleys">구불구불한 골목망</option><option value="previous">이전 사각 구획 · 비교</option></select><button id="layoutFocus">거리 중심 보기</button><a href="layouts.html">구조3종 한눈에 보기 →</a><span id="layoutName"></span></div><div class="toolbar">')
html=html.replace('<script src="generator.js?v=market01"></script>','<script src="legacy-generator.js"></script><script src="generator.js?v=layout04"></script>')
html=html.replace('app.js?v=market03','app.js?v=layout04')
html=html.replace('진열장·상품 더미·배송·쓰레기 소품20종과 멤버별 랜덤 굿즈를 배치합니다.','같은 도트로 큰 공간·방 연결·골목망을 다르게 생성합니다. 한 번호에서 구조를 바꿔 전체 지도와 거리 모습을 비교해보세요.')
html=html.replace('① 공간 나누기','① 큰 구조 선택')
(dst/'index.html').write_text(html,encoding='utf-8')
s=(src/'app.js').read_text(encoding='utf-8')
s=s.replace("const G=StreetGen,stages=","let layoutChoice=new URLSearchParams(location.search).get('layout')||'auto';\nconst G=StreetGen,stages=")
s=s.replace('① 공간 나누기','① 큰 구조 선택')
s=s.replace("MarketGen.generate(seed,marketFloor,$(\"exitMode\").value)","MarketGen.generate(seed,marketFloor,$(\"exitMode\").value,layoutChoice)")
s=s.replace("newMap('MARKET-001');", "$('layoutMode').value=layoutChoice;newMap(new URLSearchParams(location.search).get('seed')||'LAYOUT-001');")
s=s.replace('window.previewReady=true;',"if(new URLSearchParams(location.search).get('view')==='focus')showLayoutFocus();if(new URLSearchParams(location.search).get('view')==='overview'){overview=true;draw();}window.previewReady=true;")
s=s.replace("$('floorDescription').textContent=map.profile.detail;", "$('floorDescription').textContent=map.profile.detail;$('layoutName').textContent=map.layoutName||'이전 사각 구획';")
s=s.replace("$('stageDetail').textContent=fogEnabled?'시야7칸 · 벽 뒤는 가림 · 펜스 너머는 보임':map.profile.detail;", "$('stageDetail').textContent=fogEnabled?'시야7칸 · 벽 뒤는 가림 · 펜스 너머는 보임':map.layoutDetail;")
s=s.replace("$('marketView').onclick=()=>{stop();stage=4;overview=false;const p=map.marketWalls[Math.floor(map.marketWalls.length/2)];if(!p)return;player={x:p.x,y:p.y+1};updateVision();draw();};", "$('marketView').onclick=()=>{const p=map.marketWalls[Math.floor(map.marketWalls.length/2)];if(p)showMerchType(p.type);};")
s=s.replace('window.previewApp={setPixelQuality:',"function setLayoutMode(value){if(!['auto','plaza','rooms','alleys','previous'].includes(value))throw Error('Unknown layout');layoutChoice=value;$('layoutMode').value=value;newMap($('seed').value||'LAYOUT-001');}function showLayoutFocus(){stop();stage=4;overview=false;player={...(map.focus||map.start)};updateVision();draw();} $('layoutMode').onchange=()=>setLayoutMode($('layoutMode').value);$('layoutFocus').onclick=showLayoutFocus;\nwindow.previewApp={setLayoutMode,showLayoutFocus,setPixelQuality:")
s=s.replace('getState:()=>({pixelQuality:', 'getState:()=>({layoutChoice,layoutKey:map.layoutKey,layoutName:map.layoutName,layoutMetrics:map.metrics,placementZones:map.placementZones,pixelQuality:')
(dst/'app.js').write_text(s,encoding='utf-8')
with(dst/'style.css').open('a',encoding='utf-8')as f:f.write('\n.layout-toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:14px;background:#1d2a28;border:1px solid #526c65;border-radius:6px;margin-bottom:14px}.layout-toolbar a{color:#b2d7cd;font-size:13px}.layout-toolbar span{font-size:13px;color:#d1c69e}\n')
print('Prepared browser-only layout04 comparison; original examples preserved.')
